/**
 * LocationAutocomplete — place picker backed by OpenStreetMap Nominatim.
 *
 * Free-text is still allowed, but picking a suggestion also hands the caller
 * latitude/longitude. Typing instead of picking yields no coordinates; the API
 * treats those as "unknown" and keeps whatever fix is already stored.
 */
import * as React from 'react';
import {
    Autocomplete,
    Box,
    CircularProgress,
    InputAdornment,
    TextField,
    Typography,
} from '@mui/material';
import PlaceOutlinedIcon from '@mui/icons-material/PlaceOutlined';
import { searchPlaces, type PlaceSuggestion } from '@/api/geocoding.api';

const DEBOUNCE_MS = 450;
const MIN_QUERY_LENGTH = 3;

export interface LocationCoordinates {
    latitude: number;
    longitude: number;
}

export interface LocationAutocompleteProps {
    value: string;
    /** `coordinates` is undefined whenever the user types instead of picking. */
    onChange: (location: string, coordinates?: LocationCoordinates) => void;
    label?: string;
    placeholder?: string;
    helperText?: React.ReactNode;
    required?: boolean;
    error?: boolean;
    disabled?: boolean;
    fullWidth?: boolean;
}

export const LocationAutocomplete: React.FC<LocationAutocompleteProps> = ({
    value,
    onChange,
    label = 'Location',
    placeholder = 'Start typing a city, town or area…',
    helperText,
    required = false,
    error = false,
    disabled = false,
    fullWidth = true,
}) => {
    const [inputValue, setInputValue] = React.useState<string>(value ?? '');
    const [options, setOptions] = React.useState<PlaceSuggestion[]>([]);
    const [open, setOpen] = React.useState<boolean>(false);
    const [loading, setLoading] = React.useState<boolean>(false);
    // Label of the last picked suggestion — suppresses a redundant re-query.
    const pickedLabelRef = React.useRef<string>('');

    // Keep the visible text in sync when the parent loads/resets the form.
    React.useEffect(() => {
        setInputValue(value ?? '');
    }, [value]);

    React.useEffect(() => {
        const query = inputValue.trim();

        if (!open || query.length < MIN_QUERY_LENGTH || query === pickedLabelRef.current) {
            setLoading(false);
            return;
        }

        const controller = new AbortController();
        setLoading(true);

        const timer = window.setTimeout(() => {
            searchPlaces(query, controller.signal).then((results) => {
                if (controller.signal.aborted) return;
                setOptions(results);
                setLoading(false);
            });
        }, DEBOUNCE_MS);

        return () => {
            window.clearTimeout(timer);
            controller.abort();
        };
    }, [inputValue, open]);

    return (
        <Autocomplete
            freeSolo
            fullWidth={fullWidth}
            disabled={disabled}
            open={open}
            onOpen={() => setOpen(true)}
            onClose={() => setOpen(false)}
            options={options}
            loading={loading}
            value={value ?? ''}
            inputValue={inputValue}
            autoComplete
            includeInputInList
            // Results are already ranked by the provider — never re-filter locally.
            filterOptions={(opts) => opts}
            getOptionLabel={(option) => (typeof option === 'string' ? option : option.label)}
            isOptionEqualToValue={(option, selected) =>
                typeof option === 'string' || typeof selected === 'string'
                    ? option === selected
                    : option.id === selected.id
            }
            noOptionsText={
                inputValue.trim().length < MIN_QUERY_LENGTH
                    ? 'Type at least 3 characters'
                    : 'No matching places'
            }
            onInputChange={(_event, newInput, reason) => {
                setInputValue(newInput);
                if (reason === 'input' || reason === 'clear') {
                    pickedLabelRef.current = '';
                    onChange(newInput);
                }
            }}
            onChange={(_event, selected) => {
                if (!selected) {
                    pickedLabelRef.current = '';
                    onChange('');
                    return;
                }
                if (typeof selected === 'string') {
                    pickedLabelRef.current = '';
                    onChange(selected);
                    return;
                }
                pickedLabelRef.current = selected.label;
                setInputValue(selected.label);
                onChange(selected.label, {
                    latitude: selected.latitude,
                    longitude: selected.longitude,
                });
            }}
            renderOption={(props, option) => {
                const { key, ...optionProps } = props as React.HTMLAttributes<HTMLLIElement> & { key: string };
                return (
                    <Box component="li" key={key} {...optionProps} sx={{ alignItems: 'flex-start', gap: 1.25 }}>
                        <PlaceOutlinedIcon fontSize="small" sx={{ mt: '2px', color: 'text.disabled' }} />
                        <Box sx={{ minWidth: 0 }}>
                            <Typography variant="body2" sx={{ fontWeight: 600 }} noWrap>
                                {option.primary}
                            </Typography>
                            {option.secondary && (
                                <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }}>
                                    {option.secondary}
                                </Typography>
                            )}
                        </Box>
                    </Box>
                );
            }}
            renderInput={(params) => (
                <TextField
                    {...params}
                    label={label}
                    placeholder={placeholder}
                    required={required}
                    error={error}
                    helperText={helperText}
                    slotProps={{
                        ...params.slotProps,
                        input: {
                            ...params.slotProps.input,
                            startAdornment: (
                                <>
                                    <InputAdornment position="start">
                                        <PlaceOutlinedIcon fontSize="small" color={error ? 'error' : 'action'} />
                                    </InputAdornment>
                                    {params.slotProps.input.startAdornment}
                                </>
                            ),
                            endAdornment: (
                                <>
                                    {loading ? <CircularProgress color="inherit" size={18} /> : null}
                                    {params.slotProps.input.endAdornment}
                                </>
                            ),
                        },
                    }}
                />
            )}
        />
    );
};
